insert into core.fact (id,place_id,property,scope,value_num,value_text,unit,qualifiers,season,method,source_id,dataset_id,retrieved_at,status,legacy_ref,note,created_by)
select v.id,v.place_id,v.property,v.scope,v.value_num::numeric,v.value_text,v.unit,coalesce(nullif(v.q,''),'{}')::jsonb,v.season,v.method,s.id,d.id,'2026-10-26','draft',v.legacy_ref,v.note,'loader' from v left join s on s.k=v.sk left join d on d.k=v.dk;


select setval('core.fact_seq', greatest((select last_value from core.fact_seq), 817));
